module.exports.ENGINE_SRC="const I18N={};\nI18N.fr={_adj:['Cobalt','Fulgurant','Pourpre','Stellaire','Vif','Polaire','Ardent','Lunaire','Électrique','Sombre','Radieux','Quantique'],_noun:['Hexagone','Prisme','Pentagone','Comète','Spirale','Vecteur','Nova','Pulsar','Octogone','Photon','Orbite','Fractale'],_days:['dimanche','lundi','mardi','mercredi','jeudi','vendredi','samedi'],_units:['k','M','Md','Bn'],_dur:['s','min','h','j'],name_short:'3 caractères minimum.',name_long:'16 caractères maximum.',name_cost:'Il te faut {n} gemmes.'};\nI18N.en={_adj:['Cobalt','Blazing','Crimson','Stellar','Swift','Polar','Fiery','Lunar','Electric','Shadow','Radiant','Quantum'],_noun:['Hexagon','Prism','Pentagon','Comet','Spiral','Vector','Nova','Pulsar','Octagon','Photon','Orbit','Fractal'],_days:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],_units:['K','M','B','T'],_dur:['s','min','h','d'],name_short:'3 characters minimum.',name_long:'16 characters maximum.',name_cost:'You need {n} gems.'};\nI18N.es={_adj:['Cobalto','Fulgurante','Púrpura','Estelar','Veloz','Polar','Ardiente','Lunar','Eléctrico','Sombrío','Radiante','Cuántico'],_noun:['Hexágono','Prisma','Pentágono','Cometa','Espiral','Vector','Nova','Púlsar','Octógono','Fotón','Órbita','Fractal'],_days:['domingo','lunes','martes','miércoles','jueves','viernes','sábado'],_units:['k','M','MM','B'],_dur:['s','min','h','d'],name_short:'3 caracteres como mínimo.',name_long:'16 caracteres como máximo.',name_cost:'Necesitas {n} gemas.'};\nI18N.de={_adj:['Kobalt','Blitzend','Purpur','Stellar','Flink','Polar','Glühend','Lunar','Elektrisch','Dunkel','Strahlend','Quanten'],_noun:['Sechseck','Prisma','Fünfeck','Komet','Spirale','Vektor','Nova','Pulsar','Achteck','Photon','Orbit','Fraktal'],_days:['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'],_units:['Tsd.','Mio.','Mrd.','Bio.'],_dur:['s','Min.','Std.','T.'],name_short:'Mindestens 3 Zeichen.',name_long:'Höchstens 16 Zeichen.',name_cost:'Du brauchst {n} Edelsteine.'};\nI18N.pt={_adj:['Cobalto','Fulgurante','Púrpura','Estelar','Veloz','Polar','Ardente','Lunar','Elétrico','Sombrio','Radiante','Quântico'],_noun:['Hexágono','Prisma','Pentágono','Cometa','Espiral','Vetor','Nova','Pulsar','Octógono','Fotão','Órbita','Fractal'],_days:['domingo','segunda','terça','quarta','quinta','sexta','sábado'],_units:['mil','mi','bi','tri'],_dur:['s','min','h','d'],name_short:'Mínimo de 3 caracteres.',name_long:'Máximo de 16 caracteres.',name_cost:'Precisas de {n} gemas.'};\nI18N.it={_adj:['Cobalto','Fulminante','Purpureo','Stellare','Vivace','Polare','Ardente','Lunare','Elettrico','Oscuro','Radioso','Quantico'],_noun:['Esagono','Prisma','Pentagono','Cometa','Spirale','Vettore','Nova','Pulsar','Ottagono','Fotone','Orbita','Frattale'],_days:['domenica','lunedì','martedì','mercoledì','giovedì','venerdì','sabato'],_units:['k','M','Mrd','Bln'],_dur:['s','min','h','g'],name_short:'Minimo 3 caratteri.',name_long:'Massimo 16 caratteri.',name_cost:'Ti servono {n} gemme.'};\nlet LANG='fr';\nconst LANG_LIST=()=>Object.keys(I18N);\nfunction pickLang(){try{const s=localStorage.getItem('prisme-lang');if(s&&I18N[s])return s;}catch(e){}const nav=(navigator.languages||[navigator.language||'fr']).map(x=>x.slice(0,2).toLowerCase());for(const l of nav)if(I18N[l])return l;return 'en';}\nfunction setLang(l){if(!I18N[l])return;LANG=l;try{localStorage.setItem('prisme-lang',l);}catch(e){}}\n/* t('clé',{n:3}) : remplace {n} ; {n|s} ajoute « s » si n>1 (ou la chaîne donnée) */\nfunction t(k,v){let s=I18N[LANG][k];if(s==null)s=I18N.fr[k];if(s==null)return k;if(!v)return s;return s.replace(/\\{(\\w+)(?:\\|([^}]*))?\\}/g,(m,key,pl)=>{const val=v[key];if(pl!==undefined){const many=+String(val).replace(/[^\\d.]/g,'')>1;if(pl.includes('/')){const [a,b]=pl.split('/');return many?b:a;}return many?pl:'';}return val==null?'':String(val);});}\n/* nombres : séparateurs de la langue, décimales locales */\nconst dec=(v,d=1)=>{try{return new Intl.NumberFormat(LANG,{minimumFractionDigits:0,maximumFractionDigits:d}).format(+v.toFixed(d));}catch(e){return v.toFixed(d);}};\nconst grp=n=>{try{return new Intl.NumberFormat(LANG).format(n);}catch(e){return String(n);}};\n\n/* ================= utilitaires ================= */\nconst $=id=>document.getElementById(id);\nconst U=()=>I18N[LANG]._units||I18N.fr._units;\nfunction fmt(n){\n  if(!isFinite(n))return '∞';\n  n=Math.floor(n);\n  if(n<10000)return grp(n);\n  let e=Math.floor(Math.log10(n)/3);let v=n/Math.pow(10,e*3);\n  if(v>=999.5){e++;v=n/Math.pow(10,e*3);}\n  const suf=e<=4?U()[e-1]:String.fromCharCode(97+Math.floor((e-5)/26)%26)+String.fromCharCode(97+(e-5)%26);\n  return (v<100?dec(v,1):dec(v,0))+'\\u202f'+suf;\n}\nconst rnd=(a,b)=>a+Math.random()*(b-a);\nconst dur=s=>{s=Math.max(0,Math.ceil(s));const U=(I18N[LANG]._dur||I18N.fr._dur);if(s<60)return s+' '+U[0];if(s<3600)return Math.ceil(s/60)+' '+U[1];if(s<86400){const h=Math.floor(s/3600),m=Math.floor(s%3600/60);return h+' '+U[2]+(m?' '+String(m).padStart(2,'0'):'');}const d=Math.floor(s/86400),h=Math.floor(s%86400/3600);return d+' '+U[3]+(h?' '+h+' '+U[2]:'');};\nconst clock=s=>{s=Math.max(0,Math.floor(s));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');};\nlet TZOFF=null; // côté serveur : décalage du joueur en minutes (−getTimezoneOffset) ; null = heure locale de l'appareil\nfunction dparts(t){if(TZOFF==null){const d=new Date(t);return [d.getFullYear(),d.getMonth(),d.getDate(),d.getDay()];}const d=new Date(t+TZOFF*60000);return [d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),d.getUTCDay()];}\nfunction dayKey(t=Date.now()){const [y,m,d]=dparts(t);return y+'-'+(m+1)+'-'+d;}\nfunction weekKey(t=Date.now()){const [y,m,d,wd]=dparts(t);const mon=new Date(Date.UTC(y,m,d-((wd+6)%7)));return mon.getUTCFullYear()+'-'+(mon.getUTCMonth()+1)+'-'+mon.getUTCDate();}\nconst dayOfWeek=(t=Date.now())=>dparts(t)[3];\nconst esc=s=>String(s).replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[ch]));\nconst ic=(n,c='')=>`<svg class=\"i ${c}\" aria-hidden=\"true\"><use href=\"#i-${n}\"/></svg>`;\nconst I={e:ic('bolt','ie'),g:ic('gem','ig'),s:ic('shard','is')};\n\n/* ================= pseudos ================= */\nconst ADJ=['Cobalt','Fulgurant','Pourpre','Stellaire','Vif','Polaire','Ardent','Lunaire','Électrique','Sombre','Radieux','Quantique'];\nconst NOUN=['Hexagone','Prisme','Pentagone','Comète','Spirale','Vecteur','Nova','Pulsar','Octogone','Photon','Orbite','Fractale'];\nconst randomName=()=>{const L=I18N[LANG]||I18N.fr,A=L._adj||ADJ,N=L._noun||NOUN;return N[Math.floor(Math.random()*N.length)]+' '+A[Math.floor(Math.random()*A.length)]+' '+Math.floor(rnd(10,999));};\nconst BAN_SUB=['connard','connasse','salope','salaud','pute','putain','encule','enculer','merde','bite','couille','nique','niquer','batard','enfoire','fuck','shit','bitch','cunt','dick','nigg','negr','nazi','hitler','whore','faggot','pussy','asshole','retard','slut','pedo','viol','tapette','gouine','bougnoul','youpin','chienne','puta','mierda','joder','cabron','maricon','pendejo','scheisse','fotze','hurensohn','arschloch','porra','caralho','viado','buceta','cazzo','stronzo','troia','vaffanculo','frocio'];\nconst BAN_WORD=['con','conne','pd','fdp','ntm','tg','nazi','cul','fag','kkk','ss'];\nfunction normName(s){return s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/0/g,'o').replace(/[1!|]/g,'i').replace(/3/g,'e').replace(/[4@]/g,'a').replace(/[5$]/g,'s').replace(/7/g,'t');}\nfunction checkName(raw){\n  const s=raw.trim().replace(/\\s+/g,' ');\n  if(s.length<3)return {ok:false,msg:t('name_short')};\n  if(s.length>16)return {ok:false,msg:t('name_long')};\n  if(!/^[\\p{L}\\p{N} _-]+$/u.test(s))return {ok:false,msg:t('name_chars')};\n  const n=normName(s),words=n.split(/[\\s_-]+/).map(w=>w.replace(/[^a-z]/g,'')),flatRaw=n.replace(/[^a-z]/g,''),flat=flatRaw.replace(/(.)\\1+/g,'$1');\n  if(BAN_SUB.some(b=>flatRaw.includes(b)||flat.includes(b.replace(/(.)\\1+/g,'$1')))||words.some(w=>BAN_WORD.includes(w))||BAN_WORD.includes(flatRaw))return {ok:false,msg:t('name_banned')};\n  return {ok:true,name:s};\n}\n\n/* ================= réglages (tout l'équilibrage est ici) ================= */\nconst CFG={\n  board:{spawn0:2.4,spawnMin:0.35,spawnDecay:0.9},\n  dmg:{base:2.6,combo:0.12,manual:1.6},\n  shards:{kill:(n,type)=>type==='boss'?4*n:type==='mini'?n:n/25}, // éclats hors Réfraction : surtout les boss\n  sparks:{merge:l=>0.15*l,manual:2,kill:n=>0.8*Math.pow(1.18,n)*(1+2*Math.max(0,1-(n-1)/15))}, // coup de pouce ×3 à l'étage 1, fondu jusqu'à l'étage 16\n  enemy:{hp:n=>400*Math.pow(1.6,n-1)*(n%10===0?3:n%5===0?2:1)*(n<5?[0.06,0.25,0.5,0.8][n-1]:1), // v9.9 : 4 premiers ennemis allégés (premier tué en quelques secondes)\n   bossTime:60,bossRetry:60,atkEvery:9,windup:3},\n  tb:{ // boosters temporaires : coût de base, croissance, plafond\n    cad:{c0:10,g:1.45,max:30},birth:{c0:300,g:6,max:5},auto:{c0:60,g:1.55,max:30},power:{c0:25,g:1.45,max:40,m:1.12},spark:{c0:50,g:1.5,max:30,m:1.08}}, // v12.2 : m = effet par niveau (Force et Gain absorbent Puissance et Étincelles)\n  prestige:{minStage:30,mult:0.2,shards:n=>Math.floor(10*Math.pow(1.15,n)),ppX:1.5,first:2}, // first : points offerts à la première Réfraction (de quoi débloquer l'auto-fusion et l'achat auto)\n  refr:{reset:['atk','grid','eco'],memCost:0.5,runCost:3,ppAuto:k=>Math.min(3,1+Math.floor(k/3))}, // v9.4 : Attaque/Plateau/Économie repartent à zéro à chaque Réfraction ; « mémoire » = re-recherche instantanée et moitié prix ; automatisations payées en points de réfraction\n  offline:{capH:k=>2+k,rateWindow:60,factor:0.3},\n  titan:{time:45,days:[2,4,6],free:2,ticketGems:20}, // jours : 0 = dimanche\n  build:{timeX:1.5,gemSec:300,adCut:1800,slotGems:[300,600],jslotGems:[200,400]},\n  boost:{adH:1,loginH:2,gemsH:4,gemsPrice:25},\n  interstitialEvery:4,wpReset:50,\n  gift:{every:[150,300],show:45,gemCap:30}, // v9.8 : au plus 30 gemmes par jour venant des cadeaux\n  chest:{cap:600,open:300,price:2.99},\n  pass:{price:4.99,tiers:100,xp:15,q:{o:10,d:10,w:30,login:10},dupe:150,tierGems:15,tier10:120,perks:{offH:4,slot:1,xp:2},v:2}, // v12 : palier 15 gemmes, lot de 10 à 120 ; avantages premium pendant la saison\n  weekOffer:[{id:'prod',g:60,m:240},{id:'boost',g:25,b:6},{id:'mix',g:50,m:120,b:3}], // v11 : 100 paliers de 15 points ; un palier s'achète 20 gemmes (plus cher que ce qu'il rapporte)\n  shopGift:{g:5}, // v10 : cadeau gratuit quotidien de la boutique\n  // v10.6 : alerte de dépenses retirée (décision de Lucas) ; S.spend reste un simple total du mois, non affiché // v9.8 : coffre de gemmes, 1 gemme pour 2 gemmes gratuites gagnées\n  rate:{window:120}, // référence : étincelles gagnées sur 2 min, hors boost ×2 publicitaire\n  ads:{giftMin:10,shopMin:30,floor:{gift:60,shop:200},cap:{shop:5,boost:3,build:6}}, // v9.7 : plafonds journaliers des pubs (sans eux, une pub toutes les 40 s rendait les achats en gemmes inutiles) // pubs = minutes de production, avec un minimum en étincelles\n  league:{gems:r=>r===1?60:r===2?40:r===3?30:r<=5?20:r<=15?10:r<=25?5:2,minutes:r=>r===1?120:r<=3?60:r<=5?45:r<=15?30:r<=25?15:10,tiers:[[1,1],[2,2],[3,3],[4,5],[6,15],[16,25],[26,30]]}, // récompenses de fin de semaine (gemmes validées par le serveur, étincelles = minutes de production)\n  guild:{size:30,create:100,tiers:[200,600,1500,3000,6000],rewards:[{g:5,min:20},{g:10,min:45},{g:20,min:90},{g:35,min:180},{g:60,min:360,b:4}],pts:[10,20,30]}, // guilde : jauge hebdo = somme des points de quêtes de guilde des membres ; récompenses par palier, pour chaque membre\n  sparkShop:{packs:[{g:20,min:30},{g:50,min:90},{g:100,min:240},{g:200,min:600}],capMin:1440}, // gemmes → étincelles, 24 h de production max par jour\n};\nconst THEMES=[0,1,2,3,4].map(i=>({get mob(){return t('th'+i+'_mob')},get mini(){return t('th'+i+'_mini')},get boss(){return t('th'+i+'_boss')},get titan(){return t('th'+i+'_titan')},atk:['lock','burn','fog','heal','shuffle'][i],get atkT(){return t('th'+i+'_atk')}}));\nconst WORLDS=[{h:188,k:0},{h:22,k:-3},{h:255,k:2},{h:145,k:-5},{h:310,k:5}].map((w,i)=>Object.defineProperty(w,'n',{get(){return t('w'+i)},enumerable:true}));\nconst worldOf=n=>Math.floor((n-1)/10)+1;\nfunction worldInfo(w){const b=WORLDS[(w-1)%WORLDS.length];const cyc=Math.floor((w-1)/WORLDS.length);return {name:b.n+(cyc?' '+['II','III','IV','V','VI','VII','VIII','IX','X'][Math.min(cyc-1,8)]:''),h:b.h,k:b.k,col:`hsl(${b.h} 100% 62%)`};}\n\n/* ---------- atelier : recherches ---------- */\n/* ---------- armes : la forme de la gemme (cycle de 8) ---------- */\nconst WEAPONS=[['tri',0.55,0.45,'94,200,255'],['sq',1.2,1,'157,123,255'],['pen',1.5,1,'255,94,126'],['hex',1.3,1,'255,230,109'],['hep',1.3,1,'255,179,71'],['oct',1.6,1.1,'127,226,255'],['star',1.2,0.9,'108,240,194'],['dia',1.4,0.8,'212,140,255']].map(([id,rate,k,col])=>({id,rate,k,col,get t(){return t('wp_'+id)},get fx(){return t('wp_'+id+'_fx')},get d(){return t('wp_'+id+'_d')}}));\nconst weaponOf=l=>WEAPONS[(l-1)%8];\nconst rankOf=l=>Math.floor((l-1)/8);\n/* points de réfraction : gagnés à chaque réfraction, dépensés librement dans les armes */\nconst ppGain=n=>n<CFG.prestige.minStage?0:Math.max(1,Math.floor(CFG.prestige.ppX*(1+(n-CFG.prestige.minStage)/10)*(1+0.1*(S.up.eveil||0))));\nconst wpLvl=i=>(S.wp&&S.wp[i])||0;\nconst wpCost=i=>1+wpLvl(i);\nfunction buyWP(i){const c=wpCost(i);if(S.pp<c)return false;S.pp-=c;S.wp=S.wp||{};S.wp[i]=wpLvl(i)+1;return true;}\nfunction resetWP(){if(S.gems<CFG.wpReset)return false;S.gems-=CFG.wpReset;let back=0;for(const i in S.wp){const k=S.wp[i];back+=k*(k+1)/2;}S.wp={};S.pp+=back;return true;}\nconst wIdx=l=>(l-1)%8;\nconst effectPow=l=>(1+0.5*rankOf(l))*(1+0.2*wpLvl(wIdx(l)))*(1+0.1*(S.up.rang||0));\nconst wpDmg=l=>1+0.08*wpLvl(wIdx(l));\nconst GROUPS=['start','auto','atk','grid','eco','jok','arm'].map(id=>({id,get t(){return t('g_'+id)},get d(){return t('g_'+id+'_d')}}));\nconst T=(a,g,cap=2592000)=>k=>Math.min(cap,Math.round(a*Math.pow(g,k))); // plafond 30 jours : les recherches deviennent de plus en plus longues\nconst UPG=[\n  // Départ : niveau de départ des boosters temporaires\n  {id:'st_cad',g:'start',get t(){return t('u_st_cad')},d:k=>t('u_st_cad_d',{n:k+1}),c:k=>60*Math.pow(1.35,k),time:T(20,1.25),max:Infinity},\n  {id:'st_auto',g:'start',get t(){return t('u_st_auto')},d:k=>t('u_st_auto_d',{n:k+1}),c:k=>150*Math.pow(1.4,k),time:T(45,1.25),max:Infinity,req:6},\n  {id:'st_power',g:'start',get t(){return t('u_st_power')},d:k=>t('u_st_power_d',{n:k+1}),c:k=>120*Math.pow(1.25,k),time:T(40,1.25),max:Infinity},\n  {id:'st_birth',g:'start',get t(){return t('u_st_birth')},d:k=>t('u_st_birth_d',{n:2+k}),c:k=>400*Math.pow(2.5,k),time:T(120,1.35),max:Infinity,req:12},\n  {id:'st_spark',g:'start',get t(){return t('u_st_spark')},d:k=>t('u_st_spark_d',{n:k+1}),c:k=>200*Math.pow(1.4,k),time:T(60,1.25),max:Infinity,req:8},\n  {id:'st_bank',g:'start',get t(){return t('u_st_bank')},d:k=>t('u_st_bank_d',{n:fmt(50*Math.pow(2.2,k))}),c:k=>90*Math.pow(1.6,k),time:T(30,1.3),max:Infinity},\n  // Automatisation\n  {id:'au_merge',g:'auto',get t(){return t('u_au_merge')},d:k=>t('u_au_merge_d',{n:30*(k+1)}),c:k=>300*Math.pow(1.35,k),time:T(60,1.25),max:12,req:5},\n  {id:'au_buy',g:'auto',get t(){return t('u_au_buy')},d:k=>k?t('u_au_buy_d',{n:Math.max(1,10-k)}):t('u_au_buy_d0'),c:k=>2500*Math.pow(1.4,k),time:T(900,1.25),max:9,req:15},\n  {id:'au_joker',g:'auto',get t(){return t('u_au_joker')},d:()=>t('u_au_joker_d'),c:()=>8000,time:()=>7200,max:1,req:20},\n  {id:'au_boss',g:'auto',get t(){return t('u_au_boss')},d:k=>t('u_au_boss_d',{n:Math.max(10,60-10*(k+1))}),c:k=>4000*Math.pow(1.45,k),time:T(1800,1.3),max:5,req:20},\n  {id:'au_prestige',g:'auto',get t(){return t('u_au_prestige')},d:k=>t('u_au_prestige_d',{n:[100,50,25,10,5][Math.min(k,4)]}),c:k=>30000*Math.pow(1.6,k),time:T(14400,1.3),max:5,req:30},\n  {id:'au_exped',g:'auto',get t(){return t('u_au_exped')},d:k=>t('u_au_exped_d',{n:2*(k+1)}),c:k=>15000*Math.pow(1.7,k),time:T(7200,1.3),max:10,req:25},\n  {id:'eveil',g:'refr',get t(){return t('u_eveil')},d:k=>t('u_eveil_d',{n:10*(k+1)}),c:()=>0,time:()=>0,max:10,req:30}, // v12.2 : Éveil payé en points de réfraction\n  {id:'au_titan',g:'auto',get t(){return t('u_au_titan')},d:k=>t('u_au_titan_d',{n:k+1}),c:k=>20000*Math.pow(1.55,k),time:T(10800,1.3),max:5,req:35},\n  // Attaque\n  {id:'crit',g:'atk',get t(){return t('u_crit')},d:k=>t('u_crit_d',{n:2*(k+1)}),c:k=>500*Math.pow(1.5,k),time:T(120,1.3),max:25,req:8},\n  {id:'combo',g:'atk',get t(){return t('u_combo')},d:k=>t('u_combo_d',{n:5+(k+1)}),c:k=>400*Math.pow(1.5,k),time:T(90,1.3),max:20,req:6},\n  {id:'bossdmg',g:'atk',get t(){return t('u_bossdmg')},d:k=>t('u_bossdmg_d',{n:dec(Math.pow(1.15,k+1),1)}),c:k=>1500*Math.pow(1.55,k),time:T(600,1.3),max:Infinity,req:10},\n  {id:'pierce',g:'atk',get t(){return t('u_pierce')},d:k=>t('u_pierce_d',{n:k+1}),c:k=>20000*Math.pow(2.5,k),time:T(14400,1.4),max:4,req:20},\n  // Plateau\n  {id:'lucky',g:'grid',get t(){return t('u_lucky')},d:k=>t('u_lucky_d',{n:3*(k+1)}),c:k=>200*Math.pow(1.45,k),time:T(60,1.25),max:25},\n  {id:'chain',g:'grid',get t(){return t('u_chain')},d:k=>t('u_chain_d',{n:3*(k+1)}),c:k=>350*Math.pow(1.5,k),time:T(90,1.3),max:25,req:8},\n  {id:'gold',g:'grid',get t(){return t('u_gold')},d:k=>t('u_gold_d',{n:k+1}),c:k=>600*Math.pow(1.55,k),time:T(240,1.3),max:20,req:12},\n  {id:'board',g:'start',get t(){return t('u_board')},d:k=>k?t('u_board_d1'):t('u_board_d0'),c:k=>[400,60000][k],time:k=>[7200,86400][k],max:2,req:k=>k?30:12},\n  {id:'sursis',g:'grid',get t(){return t('u_sursis')},d:k=>t('u_sursis_d',{n:k+2}),c:k=>1200*Math.pow(1.7,k),time:T(600,1.3),max:6,req:10},\n  // Économie\n  {id:'loot',g:'eco',get t(){return t('u_loot')},d:k=>t('u_loot_d',{n:8*(k+1)}),c:k=>300*Math.pow(1.4,k),time:T(120,1.25),max:Infinity},\n  {id:'off',g:'start',get t(){return t('u_off')},d:k=>t('u_off_d',{n:2+k+1}),c:k=>500*Math.pow(1.6,k),time:T(900,1.3),max:Infinity,req:5},\n  {id:'killspark',g:'eco',get t(){return t('u_killspark')},d:k=>t('u_killspark_d',{n:15*(k+1)}),c:k=>800*Math.pow(1.45,k),time:T(300,1.25),max:Infinity,req:10},\n  // Jokers\n  {id:'catal',g:'jok',get t(){return t('u_catal')},d:k=>t('u_catal_d',{n:8*(k+1)}),c:k=>2000*Math.pow(1.6,k),time:T(900,1.35),max:8,req:8},\n];\nconst ARMUP=[\n  {id:'cadence',g:'arm',get t(){return t('u_cadence')},d:k=>t('u_cadence_d',{n:5*(k+1)}),c:k=>150*Math.pow(1.4,k),time:T(40,1.25),max:Infinity},\n  {id:'rang',g:'arm',get t(){return t('u_rang')},d:k=>t('u_rang_d',{n:10*(k+1)}),c:k=>600*Math.pow(1.5,k),time:T(120,1.3),max:Infinity,req:8},\n  {id:'brule',g:'arm',get t(){return t('u_brule')},d:k=>t('u_brule_d',{n:3+(k+1)}),c:k=>800*Math.pow(1.6,k),time:T(300,1.3),max:Infinity,req:12},\n  {id:'aura',g:'arm',get t(){return t('u_aura')},d:k=>t('u_aura_d',{n:25+10*(k+1)}),c:k=>1200*Math.pow(1.6,k),time:T(300,1.3),max:Infinity,req:16},\n];\nUPG.push(...ARMUP);\nconst JOKERS=[['chameleon',8,1500,50,14,l=>t('j_chameleon_d',{p:l>=4?t('j_two'):t('j_one'),n:1+l})],['magnet',12,4000,100,22,l=>t('j_magnet_d',{n:2+l})],['surge',16,9000,100,20,l=>t('j_surge_d',{n:6+2*l})],['frost',22,20000,150,18,l=>t('j_frost_d',{n:8+2*l})],['prism',28,45000,200,22,l=>t('j_prism_d',{n:2+l})],['meteor',35,100000,200,28,l=>t('j_meteor_d',{x:l>1?', ×'+dec(1+0.5*(l-1),1):''})],['breaker',45,250000,250,16,l=>t('j_breaker_d',{n:8+3*l})]].map(([id,lvl,sh,gm,base,d])=>({id,lvl,sh,gm,base,d,get t(){return t('j_'+id)}}));\nconst JUPG=JOKERS.map(j=>({id:'j_'+j.id,g:'jok',joker:j.id,get t(){return j.t},d:k=>j.d(k+1),c:k=>j.sh*0.8*Math.pow(2.2,k-1),time:k=>Math.min(86400,Math.round(1200*Math.pow(2.5,k-1))),max:5}));\nconst ALLUP=UPG.concat(JUPG);\nconst TBDEF={cad:{i:'hourglass',c:'s5',n:k=>t('tb_cad_n',{n:dec(CFG.board.spawn0*Math.pow(CFG.board.spawnDecay,k),1)})},birth:{i:'gem',c:'s4',n:k=>t('tb_birth_n',{n:1+k})},auto:{i:'link',c:'s6',n:k=>k?t('tb_auto_n',{n:dec(0.12*k*(1+0.3*S.up.au_merge),2)}):t('tb_auto_0')},power:{i:'swords',c:'s1',n:k=>t('tb_power_n',{n:dec(Math.pow(CFG.tb.power.m,k),1)})},spark:{i:'spark',c:'s3',n:k=>t('tb_spark_n',{n:dec(Math.pow(CFG.tb.spark.m,k),2)})}};\nfor(const k in TBDEF){Object.defineProperty(TBDEF[k],'t',{get(){return t('tb_'+k)}});Object.defineProperty(TBDEF[k],'d',{get(){return t('tb_'+k+'_d')}});}\n\n/* ================= état du joueur ================= */\n/* v12.1 : chaque couleur portée donne un bonus (achetées uniquement en gemmes) ; chaque couleur possédée ajoute +1 % d'étincelles (collection) */\nconst SKINS=[{id:'cyan',price:0,c:'#3ef2ff',h:192},{id:'rose',price:100,c:'#ff3ec8',h:322,bn:{dmg:0.05}},{id:'or',price:200,c:'#ffd23e',h:44,bn:{sp:0.08}},{id:'emeraude',price:300,c:'#3effa0',h:150,bn:{res:0.08}},{id:'saphir',price:300,c:'#3e7bff',h:222,bn:{cad:0.08}},{id:'prisme',price:400,c:'rainbow',h:-1,bn:{sp:0.06,dmg:0.06}},{id:'rubis',price:500,c:'#ff3e5e',h:352,bn:{dmg:0.12}},{id:'obsidienne',price:800,c:'#9a6bff',h:262,bn:{jok:0.15,off:0.1}},{id:'aurore',price:1200,c:'aurora',h:-2,bn:{sp:0.15,cad:0.05}},{id:'solaire',price:2000,c:'solar',h:-3,bn:{dmg:0.2,sp:0.1}},{id:'saison',price:0,pass:true,c:'#7dff6a',h:110,bn:{off:0.1}}].map(k=>Object.defineProperty(k,'label',{get(){return t('skin_'+k.id)},enumerable:true}));\nfunction fresh(){\n  const now=Date.now();\n  return {v:3,gems:20,maxStage:1,bestStage:1,prestiges:0,\n    run:{sparks:0,stage:1,tb:{cad:0,birth:0,auto:0,power:0,spark:0},max:1,fled:false,fledAt:0,rate:0,srate:0},\n    up:Object.fromEntries(UPG.map(u=>[u.id,0])),jk:{},equip:[],jslots:1,build:[],slots:1,\n    pp:0,wp:{},mem:{},lastSeen:now,boostUntil:0,titan:null,lootX2:false,noAds:false,starter:false,adCount:0,firstX2:false,pass:null,spend:null,\n    name:randomName(),nameChanges:0,flagged:0,skin:'cyan',skins:['cyan'],medals:{},\n    st:{tuto:0,merges:0,manual:0,kills:0,bosses:0,collects:0,bought:0,started:0,jokerUses:0,maxCombo:0,days:1,lastDay:dayKey(),titans:0,titanBest:0,namePrompted:false,hintW:1},\n    day:{k:dayKey(),merges:0,kills:0,bosses:0,ads:0,buildAds:0,collects:0,jokers:0,titans:0,tb:0,gifts:0,combo:0,prestiges:0,started:0,claimed:[],gq:[]},\n    week:{k:weekKey(),best:0,kills:0,prestiges:0,collects:0,titans:0,claimed:[]},\n    onb:[],league:null,bestiary:{},login:{streak:0,last:'',claimed:''},offerAt:0,settings:{music:true,sound:true,fx:true}};\n}\nlet S=fresh();\nconst KEY='prisme-fusion-v7';\nfunction load(){try{const r=localStorage.getItem(KEY);if(r){const o=JSON.parse(r);if(o&&o.v===3){const f=fresh();const merged=Object.assign({},f,o);for(const k of ['up','st','settings','run','day','week','login','wp'])merged[k]=Object.assign({},f[k],o[k]||{});merged.run.tb=Object.assign({},f.run.tb,(o.run||{}).tb||{});migrate(merged);S=merged;}}}catch(e){}}\nfunction snapBoard(){if(!R||!R.cells)return;S.run.cells=R.cells.map(c=>!c?0:c.l?(c.k==='gold'?-c.l:c.l):c.k==='joker'?'j':0);}\nfunction migrate(m){delete m.idle;if(!m.mem)m.mem={};if(Array.isArray(m.build)&&m.up)m.build=m.build.filter(b=>{const u=UPG.find(x=>x.id===b.id);if(u&&(u.g==='auto'||u.g==='refr'||CFG.refr.reset.includes(u.g))){m.up[u.id]=(m.up[u.id]||0)+1;return false;}return !!(u||ALLUP.find(x=>x.id===b.id));}); // v12.2 : améliorations de partie et Éveil immédiats : une recherche en cours est acquise ; recherche supprimée (Puissance, Étincelles) : retirée // v9.4 : automatisation en cours = acquise\n  if(m.day&&!Array.isArray(m.day.gq))m.day.gq=[];if(m.shards>0){m.run.sparks=(m.run.sparks||0)+m.shards;}delete m.shards;return m;} // v8.4 : les éclats deviennent des étincelles\nfunction save(){S.lastSeen=Date.now();snapBoard();try{localStorage.setItem(KEY,JSON.stringify(S));}catch(e){}}\nfunction roll(){passState(); /* v12.3 : pass de la saison créé des deux côtés (téléphone et serveur) */if(S.st.lastDay!==dayKey()){S.st.days++;S.st.lastDay=dayKey();}if(S.day.k!==dayKey()){S.day={k:dayKey(),merges:0,kills:0,bosses:0,ads:0,buildAds:0,collects:0,jokers:0,titans:0,tb:0,gifts:0,combo:0,prestiges:0,started:0,claimed:[],gq:[]};}if(!DAILY.length||DAILY.k!==S.day.k){pickDaily();DAILY.k=S.day.k;}if(S.week.k!==weekKey()){S.week={k:weekKey(),best:0,kills:0,prestiges:0,collects:0,titans:0,merges:0,bosses:0,claimed:[]};S.league=null;}if(WEEKLY.k!==S.week.k){pickWeekly();WEEKLY.k=S.week.k;}}\nfunction give(r){if(!r)return;if(r.g)S.gems+=r.g;if(r.s)S.run.sparks+=r.s;if(r.sp)S.run.sparks+=r.sp;if(r.b)S.boostUntil=Math.max(Date.now(),S.boostUntil)+r.b*3600e3;}\nfunction rewardHtml(r){const o=[];if(r.g)o.push(`<span>${I.g}${r.g}</span>`);if(r.s)o.push(`<span>${ic('spark','ie')}${fmt(r.s)}</span>`);if(r.sp)o.push(`<span>${ic('spark','ie')}${fmt(r.sp)}</span>`);if(r.b)o.push(`<span>${ic('bolt','ie')}${t('boost_h',{n:r.b})}</span>`);return `<span class=\"rew\">${o.join('')}</span>`;}\nconst boosted=()=>Date.now()<S.boostUntil;\n/* ---------- cadeaux : une bulle apparaît de temps en temps, une pub = un bonus ---------- */\nfunction giftRoll(){\n  const r=Math.random(),st=Math.max(S.bestStage,1);\n  if(r<0.6)return {k:'sp',v:adSparks('gift')};\n  if(r<0.85){const left=CFG.gift.gemCap-(S.day.gg|0);if(left>=5)return {k:'g',v:Math.min(left,5+Math.floor(Math.random()*6))};return {k:'sp',v:adSparks('gift')};}\n  return {k:'b',v:0.5};\n}\nfunction giftOK(){roll();return true;}\nconst pushBase=sp=>pushWin(R.baseWin,R.t,sp/(boosted()?2:1),CFG.rate.window);\nconst rateMin=()=>(S.run.brate||0)*60; // étincelles par minute, référence des pubs et des packs\nconst adSparks=kind=>Math.max(CFG.ads.floor[kind],Math.floor(rateMin()*CFG.ads[kind+'Min']));\nconst packSparks=p=>Math.max(Math.round(CFG.ads.floor.shop*p.min/30),Math.floor(rateMin()*p.min)); /* v11.8 : plancher proportionnel à la durée (avant : 200 pour tous les packs) */\nfunction buyPack(i){roll();const p=CFG.sparkShop.packs[i];if(!p||S.gems<p.g)return false;if((S.day.spMin||0)+p.min>CFG.sparkShop.capMin)return 'cap';S.gems-=p.g;S.day.spMin=(S.day.spMin||0)+p.min;S.run.sparks+=packSparks(p);return true;}\nfunction giftTake(gf){roll();S.day.gifts=(S.day.gifts||0)+1;S.st.gifts=(S.st.gifts||0)+1;S.day.ads++;if(gf.k==='s')S.run.sparks+=gf.v;else if(gf.k==='sp')S.run.sparks+=gf.v;else if(gf.k==='g'){const v=Math.max(0,Math.min(gf.v,CFG.gift.gemCap-(S.day.gg|0)));S.gems+=v;S.day.gg=(S.day.gg|0)+v;chestFill(v);}else give({b:gf.v});}\n/* coffre de gemmes : se remplit d'une gemme pour deux gemmes gratuites gagnées (jamais avec les gemmes achetées) */\nconst chestG=()=>Math.min(CFG.chest.cap,Math.floor((S.chest|0)/2));\nfunction chestFill(g){if(g>0)S.chest=Math.min(2*CFG.chest.cap,(S.chest|0)+g);}\n\n/* ================= calendrier de connexion ================= */\nconst LOGIN=[{g:10},{b:2},{s:300},{g:20},{b:4},{s:2000},{joker:true}];\nfunction loginState(){roll();const today=dayKey();if(S.login.last===today)return {day:S.login.streak,claimedToday:S.login.claimed===today};\n  const consecutive=S.login.last===dayKey(Date.now()-86400e3);\n  S.login.streak=consecutive?(S.login.streak%7)+1:1;S.login.last=today;return {day:S.login.streak,claimedToday:false};}\nfunction claimLogin(){const st=loginState();if(st.claimedToday)return false;S.login.claimed=dayKey();const r=LOGIN[st.day-1];\n  if(r.joker){const j=JOKERS.find(x=>!S.jk[x.id]);if(j){S.jk[j.id]=1;if(S.equip.length<S.jslots)S.equip.push(j.id);}else{S.gems+=50;chestFill(50);}}else{give(r);chestFill(r.g|0);}passXP(CFG.pass.q.login);return true;}\n\n\n/* ================= atelier : chantiers ================= */\nconst upById=id=>ALLUP.find(x=>x.id===id);\nconst lvlOf=u=>u.joker?(S.jk[u.joker]||0):(S.up[u.id]||0);\nconst isPP=u=>u.g==='auto'||u.g==='refr'; // v12.2 : automatisations et Éveil // automatisations : points de réfraction, sans délai, permanentes\nconst memLvl=id=>(S.mem&&S.mem[id])||0;\nconst inMem=()=>false; // v12.2 : plus de « mémoire » : les améliorations de partie sont immédiates // niveau déjà atteint avant une Réfraction\nconst upCost=u=>(u.joker&&!S.jk[u.joker])||lvlOf(u)>=u.max?Infinity:isPP(u)?CFG.refr.ppAuto(lvlOf(u)):u.c(lvlOf(u))*(CFG.refr.reset.includes(u.g)?CFG.refr.runCost:1); // v12.2 : améliorations de partie immédiates, prix ajusté (runCost)\nconst upTime=u=>isPP(u)||CFG.refr.reset.includes(u.g)?0:Math.round(Math.min(2592000,u.time(lvlOf(u))*CFG.build.timeX)*(evOn('build')?0.5:1)/bonusMul('res')); // plafond 30 jours maintenu // v12 : week-end recherches 2× plus rapides\nconst upAfford=u=>isPP(u)?(S.pp||0)>=upCost(u):S.run.sparks>=upCost(u);\nconst upReq=u=>typeof u.req==='function'?u.req(lvlOf(u)):u.req;\nconst upLocked=u=>upReq(u)&&S.bestStage<upReq(u);\nconst inBuild=id=>S.build.find(b=>b.id===id);\nfunction applyUp(id){const u=upById(id);if(u.joker)S.jk[u.joker]=(S.jk[u.joker]||0)+1;else S.up[u.id]++;S.st.bought++;if(u.id==='board')growBoard();}\nfunction growBoard(){if(!R)return;const N=boardN(),M=R.N;if(N<=M)return;const cells=Array(N*N).fill(null);R.cells.forEach((c,i)=>{if(c)cells[Math.floor(i/M)*N+(i%M)]=c;});R.N=N;R.cells=cells;snapBoard();hooks.grow&&hooks.grow(N);}\nfunction tickBuild(now=Date.now()){const done=[];S.build=S.build.filter(b=>{if(now>=b.until){applyUp(b.id);done.push(b.id);return false;}return true;});return done;}\nfunction startBuild(id,now=Date.now()){\n  tickBuild(now);const u=upById(id);if(!u)return 'none';\n  if(upLocked(u))return 'locked';if(inBuild(id))return 'busy';\n  const c=upCost(u);if(!isFinite(c))return 'max';\n  const d=upTime(u);\n  if(d>0&&S.build.length>=slotsN())return 'slots';if(!upAfford(u))return 'poor';\n  if(isPP(u))S.pp-=c;else S.run.sparks-=c;S.st.started++;S.day.started=(S.day.started|0)+1;\n  if(d<=0){applyUp(id);return 'ok';} // instantané : n'occupe pas d'emplacement\n  S.build.push({id,until:now+d*1000,dur:d});return 'ok';\n}\n/* « Tout restaurer » : rachète les niveaux en mémoire, les moins chers d'abord, tant qu'il y a des étincelles */\nconst memList=()=>UPG.filter(u=>inMem(u)&&!upLocked(u)&&!inBuild(u.id));\nconst memTotal=()=>memList().reduce((a,u)=>{let c=0;for(let k=lvlOf(u);k<Math.min(memLvl(u.id),u.max);k++)c+=u.c(k)*CFG.refr.memCost;return a+c;},0);\nfunction restoreAll(now=Date.now()){let n=0;for(let i=0;i<2000;i++){let best=null,bc=Infinity;for(const u of memList()){const c=upCost(u);if(c<bc){bc=c;best=u;}}if(!best||S.run.sparks<bc)break;if(startBuild(best.id,now)!=='ok')break;n++;}return n;}\nconst rushGems=(b,now=Date.now())=>Math.max(1,Math.ceil((b.until-now)/1000/CFG.build.gemSec));\nfunction rushBuild(id,now=Date.now()){const b=inBuild(id);if(!b)return false;const g=rushGems(b,now);if(S.gems<g)return false;S.gems-=g;b.until=now;tickBuild(now);return true;}\nfunction adBuild(id,now=Date.now()){roll();const b=inBuild(id);if(!b)return false;S.day.buildAds++;b.until-=CFG.build.adCut*1000;tickBuild(now);return true;}\nfunction buySlot(){const i=S.slots-1;if(i>=CFG.build.slotGems.length)return false;const g=CFG.build.slotGems[i];if(S.gems<g)return false;S.gems-=g;S.slots++;return true;}\nconst jokerById=id=>JOKERS.find(j=>j.id===id);\nconst jokerAvail=j=>S.bestStage>=j.lvl;\nfunction unlockJoker(id,cur){const j=jokerById(id);if(!j||S.jk[id]||!jokerAvail(j))return false;if(cur==='g'){if(S.gems<j.gm)return false;S.gems-=j.gm;}else{if(S.run.sparks<j.sh)return false;S.run.sparks-=j.sh;}S.jk[id]=1;if(S.equip.length<S.jslots)S.equip.push(id);if(R)R.jk[id]=0;return true;}\nfunction toggleEquip(id){if(!S.jk[id])return false;const i=S.equip.indexOf(id);if(i>=0){S.equip.splice(i,1);if(R)delete R.jk[id];return true;}if(S.equip.length>=S.jslots)return false;S.equip.push(id);if(R)R.jk[id]=0;return true;}\nfunction buyJSlot(){const i=S.jslots-1;if(i>=CFG.build.jslotGems.length)return false;const g=CFG.build.jslotGems[i];if(S.gems<g)return false;S.gems-=g;S.jslots++;return true;}\nconst jokerNeed=id=>{const j=jokerById(id),l=S.jk[id]||1,n=Math.max(4,Math.ceil(j.base*(1-0.08*S.up.catal))-(l-1));const m=Math.max(2,Math.ceil(n/bonusMul('jok')));return evOn('joker')?Math.max(2,Math.ceil(m/2)):m;}; // v12 : week-end jokers 2× plus rapides\n\n/* ================= boosters temporaires ================= */\nconst tbLvl=k=>S.run.tb[k]+(S.up['st_'+k]||0);\nconst tbCost=k=>S.run.tb[k]>=CFG.tb[k].max?Infinity:CFG.tb[k].c0*Math.pow(CFG.tb[k].g,S.run.tb[k]);\nfunction buyTB(k){const c=tbCost(k);if(!isFinite(c)||S.run.sparks<c)return false;S.run.sparks-=c;S.run.tb[k]++;S.day.tb=(S.day.tb||0)+1;if(k==='birth'&&R)bumpBoard();hooks.tb(k);return true;}\nfunction autoBuyTick(dt){if(!S.up.au_buy)return;R.buyT=(R.buyT||0)+dt;const every=Math.max(1,10-S.up.au_buy);if(R.buyT<every)return;R.buyT=0;\n  let best=null,bc=Infinity;for(const k in CFG.tb){const c=tbCost(k);if(c<bc){bc=c;best=k;}}if(best&&S.run.sparks>=bc)buyTB(best);}\nconst spawnLevel=()=>1+tbLvl('birth');\nconst spawnInterval=()=>Math.max(CFG.board.spawnMin,CFG.board.spawn0*Math.pow(CFG.board.spawnDecay,tbLvl('cad'))/bonusMul('cad'));\nconst autoRate=()=>{const a=tbLvl('auto');if(!a)return 0;return 0.12*a*(1+0.3*S.up.au_merge);};\nconst powerMult=()=>Math.pow(CFG.tb.power.m,tbLvl('power'))*(boosted()?2:1)*bonusMul('dmg');\nconst refMult=()=>1+CFG.prestige.mult*S.prestiges; // multiplicateur permanent d'étincelles gagné à chaque Réfraction\nconst sparkMult=()=>Math.pow(CFG.tb.spark.m,tbLvl('spark'))*(boosted()?2:1)*refMult()*(evOn('spark')?2:1)*bonusMul('sp'); // v12 : week-end étincelles ×2 ; v12.1 : couleurs et médailles\nconst lootMult=()=>(1+0.08*S.up.loot)*(S.lootX2?2:1);\nconst boardN=()=>4+S.up.board;\n\n/* ================= moteur de partie ================= */\nlet R=null;\nconst hooks={harvest(){},tb(){},milestone(){},joker(){},merge(){},kill(){},bossStart(){},bossFled(){},spawn(){},unlock(){},bomb(){},full(){},hit(){},attack(){},phase(){},windup(){},prestige(){},titanEnd(){},offline(){},evolve(){}};\nconst dmgOf=l=>Math.pow(CFG.dmg.base,l-1);\nconst themeIdx=n=>(worldOf(n)-1)%THEMES.length;\nconst weekTheme=()=>{const [y,m,d]=weekKey().split('-').map(Number);return Math.floor(Date.UTC(y,m-1,d)/(7*86400e3))%THEMES.length;}; // v12 : sans analyse de date texte (fragile hors Chrome)\nfunction enemyFor(n){\n  const type=n%10===0?'boss':n%5===0?'mini':'mob',th=themeIdx(n),max=CFG.enemy.hp(n);\n  return {type,th,name:THEMES[th][type],hp:max,max,phase:1,shieldL:0,atkT:CFG.enemy.atkEvery,atkEvery:CFG.enemy.atkEvery,str:type==='boss'?2:1,stage:n};\n}\nfunction titanEnemy(){const th=weekTheme();return {type:'titan',th,name:THEMES[th].titan,hp:Infinity,max:Infinity,phase:1,shieldL:0,atkT:99,atkEvery:99,str:1,stage:0};}\nfunction newRun(){\n  const N=boardN();\n  R={N,cells:Array(N*N).fill(null),t:0,spawnT:0,autoT:0,combo:0,comboT:0,jk:{},surgeUntil:0,frostUntil:0,breakUntil:0,paused:false,hold:false,\n    mode:'farm',bossT:0,titanT:0,titanDmg:0,dmgWin:[],sparkWin:[],baseWin:[],killWin:[],buyT:0};\n  for(const id of S.equip)if(S.jk[id])R.jk[id]=0;\n  if(S.run.fled)S.run.fledAt=0;\n  R.E=S.run.fled?enemyFor(S.run.stage-1):enemyFor(S.run.stage);\n  if(S.run.fled&&R.E.type==='boss')R.E=enemyFor(S.run.stage-1);\n  if(S.run.stage%10===0&&!S.run.fled){R.mode='boss';R.bossT=CFG.enemy.bossTime;}\n  const sv=S.run.cells;\n  const M=Array.isArray(sv)?Math.round(Math.sqrt(sv.length)):0;\n  if(M&&M*M===sv.length&&M<=N&&sv.some(Boolean)){ // plateau conservé d'une session à l'autre (recopié si la grille a grandi)\n    sv.forEach((v,i)=>{const j=M===N?i:(Math.floor(i/M))*N+(i%M);if(v==='j')R.cells[j]={k:'joker'};else if(typeof v==='number'&&v){R.cells[j]={l:Math.abs(v)};if(v<0)R.cells[j].k='gold';}});\n  }else for(let i=0;i<3;i++)spawnOne();\n  return R;\n}\nconst emptyCells=()=>R.cells.map((c,i)=>c?-1:i).filter(i=>i>=0);\nconst shapes=()=>R.cells.map((c,i)=>[c,i]).filter(x=>x[0]&&x[0].l);\nfunction bumpBoard(){const sl=spawnLevel();for(let i=0;i<R.cells.length;i++){const c=R.cells[i];if(c&&c.l&&c.l<sl){c.l=sl;hooks.spawn(i);}}}\nfunction spawnOne(){\n  let e=emptyCells();\n  if(!e.length){ // plateau plein : les plus petites gemmes se recyclent (1 de base, plus avec Sursis)\n    const n=1+S.up.sursis;const small=shapes().sort((a,b)=>a[0].l-b[0].l).slice(0,n);if(!small.length)return -1;small.forEach(([c,i])=>{R.cells[i]=null;hooks.bomb(i,[i]);});e=emptyCells();}\n  const i=e[Math.floor(Math.random()*e.length)];\n  const l=spawnLevel()+(Math.random()<0.03*S.up.lucky?1:0);R.cells[i]={l};if(Math.random()<0.01*S.up.gold)R.cells[i].k='gold';\n  hooks.spawn(i);return i;\n}\nconst nb=i=>{const N=R.N,x=i%N,y=Math.floor(i/N),o=[];if(x>0)o.push(i-1);if(x<N-1)o.push(i+1);if(y>0)o.push(i-N);if(y<N-1)o.push(i+N);return o;};\nfunction bossAttack(){\n  const E=R.E,kind=THEMES[E.th].atk,s=E.str,hit=[];\n  if(kind==='lock'){let e=emptyCells().sort(()=>Math.random()-.5);for(let k=0;k<s;k++){let i=e.pop();if(i==null){const sh=shapes().sort((a,b)=>a[0].l-b[0].l)[0];if(!sh)break;i=sh[1];}R.cells[i]={k:'lock',until:R.t+25};hit.push(i);}}\n  else if(kind==='burn'){shapes().sort((a,b)=>a[0].l-b[0].l).slice(0,s+1).forEach(([c,i])=>{R.cells[i]=null;hit.push(i);});}\n  else if(kind==='fog'){shapes().sort(()=>Math.random()-.5).slice(0,2*s+1).forEach(([c,i])=>{c.fog=R.t+8;hit.push(i);});}\n  else if(kind==='heal'){E.hp=Math.min(E.max,E.hp+E.max*0.05*s);}\n  else if(kind==='shuffle'){const idx=R.cells.map((c,i)=>i).filter(i=>!R.cells[i]||R.cells[i].k!=='lock');const vals=idx.map(i=>R.cells[i]).sort(()=>Math.random()-.5);idx.forEach((i,k)=>R.cells[i]=vals[k]);shapes().filter(([c])=>c.l>spawnLevel()).sort(()=>Math.random()-.5).slice(0,s).forEach(([c,i])=>{c.l--;hit.push(i);});}\n  hooks.attack(kind,hit);\n}\nfunction pushWin(arr,t,v,w=CFG.offline.rateWindow){arr.push([t,v]);while(arr.length&&arr[0][0]<t-w)arr.shift();}\nfunction measureRates(){const w=CFG.offline.rateWindow;S.run.srate=R.sparkWin.reduce((a,x)=>a+x[1],0)/w;S.run.brate=R.baseWin.reduce((a,x)=>a+x[1],0)/CFG.rate.window;S.run.rate=R.dmgWin.reduce((a,x)=>a+x[1],0)/w;S.run.krate=R.killWin.length/w;}\nfunction runTick(dt){\n  if(!R||R.paused||R.hold)return;\n  R.t+=dt;\n  if(R.comboT>0){R.comboT-=dt;if(R.comboT<=0)R.combo=0;}\n  for(let i=0;i<R.cells.length;i++){const c=R.cells[i];if(!c)continue;if(c.fog&&c.fog<=R.t)delete c.fog;if(c.k==='lock'&&c.until<=R.t){R.cells[i]=null;hooks.unlock(i);}}\n  const E=R.E;\n  if(R.mode==='boss'){R.bossT-=dt;if(R.t>=R.frostUntil){const b=E.atkT;E.atkT-=dt;if(b>CFG.enemy.windup&&E.atkT<=CFG.enemy.windup)hooks.windup();if(E.atkT<=0){E.atkT=E.atkEvery;bossAttack();}}\n    if(R.bossT<=0){bossFlee();}}\n  else if(R.mode==='titan'){R.titanT-=dt;if(R.titanT<=0)endTitan();}\n  else if(S.run.fled&&S.up.au_boss){R.retryT=(R.retryT||0)+dt;if(R.retryT>=Math.max(10,60-10*S.up.au_boss)){R.retryT=0;challengeBoss();}}\n  R.spawnT+=dt;const iv=spawnInterval();\n  while(R.spawnT>=iv){R.spawnT-=iv;if(spawnOne()<0){R.spawnT=0;hooks.full();break;}}\n  fireTick(dt);if(!R)return;\n  const ar=autoRate();if(ar>0){R.autoT+=dt;const ai=1/ar;while(R.autoT>=ai){R.autoT-=ai;autoMerge();}}\n  autoBuyTick(dt);\n  if(S.up.au_joker)for(const id in R.jk)if(R.jk[id]>=jokerNeed(id))useJoker(id);\n  R.rateT=(R.rateT||0)+dt;if(R.rateT>1){R.rateT=0;pushWin(R.dmgWin,R.t,0);pushWin(R.sparkWin,R.t,0);pushWin(R.baseWin,R.t,0,CFG.rate.window);measureRates();}\n}\nfunction autoMerge(){const seen={};const o=shapes().filter(x=>!x[0].fog).sort((a,b)=>a[0].l-b[0].l);for(const [c,i] of o){if(seen[c.l]!=null){runMove(seen[c.l],i,false);return true;}seen[c.l]=i;}\n  const j=R.cells.findIndex(c=>c&&c.k==='joker');if(j>=0){const cap=jokerCap(),t=o.filter(x=>x[0].l<=cap).pop();if(t){runMove(j,t[1],false);return true;}}return false;}\nfunction applyDamage(into,d,crit,w,silent){\n  const E=R.E;if(R.mode==='farm'&&S.run.fled&&E.type==='boss')return;\n  E.hp-=d;pushWin(R.dmgWin,R.t,d);\n  if(R.mode==='titan'){R.titanDmg+=d;}\n  if(!silent)hooks.hit(into,d,false,crit,w);\n  if(E.type==='boss'&&E.phase===1&&E.hp<=E.max/2&&E.hp>0){E.phase=2;E.shieldL=Math.max(1,spawnLevel()+3-S.up.pierce);E.str=3;hooks.phase('shield');}\n  if(E.hp<=0&&E.type!=='titan')onKill();\n}\nfunction fireRate(){const c=R.comboT>0?1+(0.05+0.01*S.up.combo)*R.combo:1;return (1+0.05*S.up.cadence)*c*(R.t<R.surgeUntil?2:1);}\nfunction fireOne(i,C){\n  const E=R.E,l=C.l,w=weaponOf(l),p=effectPow(l);\n  if(E.shieldL&&l<E.shieldL&&R.t>=R.breakUntil&&w.id!=='sq'){hooks.hit(i,0,true,false,w);return;}\n  let d=dmgOf(l)*w.k*powerMult()*wpDmg(l);\n  if(E.type==='boss')d*=Math.pow(1.15,S.up.bossdmg);\n  if(w.id==='dia'){}else{for(const j of nb(i)){const B=R.cells[j];if(B&&B.l&&weaponOf(B.l).id==='dia')d*=1+(0.25+0.1*S.up.aura)*effectPow(B.l);}}\n  let crit=Math.random()<0.02*S.up.crit;if(w.id==='hep'&&Math.random()<Math.min(0.9,0.25*p))crit=true;if(crit)d*=3;\n  if(w.id==='pen'){R.burn={dps:Math.max(R.burn&&R.burn.until>R.t?R.burn.dps:0,d*0.35*p),until:R.t+3+S.up.brule};}\n  if(w.id==='hex')for(const id in R.jk)R.jk[id]=Math.min(jokerNeed(id),R.jk[id]+0.5*p);\n  if(w.id==='oct'&&R.mode==='boss'){R.bossT=Math.min(R.bossT+0.4*p,CFG.enemy.bossTime);}\n  if(w.id==='star'){const sp=0.15*l*p*sparkMult();S.run.sparks+=sp;pushWin(R.sparkWin,R.t,sp);pushBase(sp);hooks.harvest(i,sp);}\n  applyDamage(i,d,crit,w);\n}\nfunction fireTick(dt){\n  const fr=fireRate();\n  for(let i=0;i<R.cells.length;i++){const C=R.cells[i];if(!C||!C.l||C.fog)continue;C.ft=(C.ft||0)+dt*fr;const w=weaponOf(C.l);if(C.ft>=w.rate){C.ft-=w.rate;fireOne(i,C);if(!R)return;}}\n  if(R.burn&&R.burn.until>R.t){applyDamage(null,R.burn.dps*dt,false,null,true);}\n}\nfunction doMerge(into,l,gold,manual){\n  R.cells[into]={l};if(gold)R.cells[into].k='gold';\n  S.st.merges++;S.day.merges++;S.week.merges=(S.week.merges|0)+1;if(manual){S.st.manual++;R.combo=Math.min(R.combo+1,30);R.comboT=3;if(R.combo>S.st.maxCombo)S.st.maxCombo=R.combo;if(R.combo>(S.day.combo||0))S.day.combo=R.combo;}\n  const sp=CFG.sparks.merge(l)*sparkMult()*(manual?CFG.sparks.manual:1);S.run.sparks+=sp;pushWin(R.sparkWin,R.t,sp);pushBase(sp);\n  if(gold)S.run.sparks+=Math.max(1,Math.round(l*lootMult()));\n  for(const id in R.jk)R.jk[id]=Math.min(jokerNeed(id),R.jk[id]+1);\n  for(const j of nb(into))if(R.cells[j]&&R.cells[j].k==='lock'){R.cells[j]=null;hooks.unlock(j);}\n  hooks.merge(into,l,gold,manual);\n  R.cells[into].ft=weaponOf(l).rate*0.8; // la gemme née tire presque tout de suite\n  if(Math.random()<0.03*S.up.chain){const k=R.cells.findIndex((c,i)=>i!==into&&c&&c.l===l&&c.k!=='lock');if(k>=0){const g2=R.cells[k].k==='gold';R.cells[k]=null;doMerge(into,l+1,gold||g2,false);}}\n}\nconst jokerCap=()=>spawnLevel()+1+(S.jk.chameleon||1);\nfunction runMove(a,b,manual=true){\n  if(!R||a===b)return 'none';\n  const A=R.cells[a],B=R.cells[b];\n  if(!A||A.k==='lock')return 'none';\n  if(B&&B.k==='lock')return 'none';\n  if(!B){R.cells[b]=A;R.cells[a]=null;return 'move';}\n  if(A.k==='joker'&&B.l&&B.l<=jokerCap()){R.cells[a]=null;doMerge(b,B.l+1,B.k==='gold',manual);return 'merge';}\n  if(B.k==='joker'&&A.l&&A.l<=jokerCap()){R.cells[a]=null;doMerge(b,A.l+1,A.k==='gold',manual);return 'merge';}\n  if(A.l&&B.l&&A.l===B.l&&!A.fog&&!B.fog){R.cells[a]=null;doMerge(b,A.l+1,A.k==='gold'||B.k==='gold',manual);return 'merge';}\n  return 'back';\n}\n/* cible aimantée : la gemme compatible la plus proche du point de dépôt (rayon 0,6 case) */\nfunction snapTarget(from,x,y){\n  const A=R.cells[from];if(!A)return null;let best=null,bd=0.6*cell;\n  for(let i=0;i<R.cells.length;i++){const B=R.cells[i];if(i===from||!B||B.k==='lock')continue;\n    const okm=(A.l&&B.l===A.l&&!A.fog&&!B.fog)||(A.k==='joker'&&B.l&&B.l<=jokerCap())||(B.k==='joker'&&A.l&&A.l<=jokerCap());if(!okm)continue;\n    const cx2=(i%R.N+.5)*cell,cy2=(Math.floor(i/R.N)+.5)*cell,d=Math.hypot(cx2-x,cy2-y);if(d<bd){bd=d;best=i;}}\n  return best;\n}\nfunction onKill(){\n  const E=R.E,n=E.stage;S.st.kills++;S.day.kills++;S.week.kills++;\n  const sp=CFG.sparks.kill(n)*(E.type==='boss'?5:E.type==='mini'?2:1)*(1+0.15*S.up.killspark)*sparkMult();S.run.sparks+=sp;pushWin(R.sparkWin,R.t,sp);pushBase(sp);pushWin(R.killWin,R.t,1);\n  if(E.type!=='mob'){const k=String(n);if(!S.bestiary[k]||R.bossT>S.bestiary[k])S.bestiary[k]=Math.round(E.type==='boss'?CFG.enemy.bossTime-R.bossT:0);if(E.type==='boss'){S.st.bosses++;S.day.bosses++;S.week.bosses=(S.week.bosses|0)+1;}}\n  const sh=CFG.shards.kill(n,E.type)*lootMult();if(sh>0){S.run.sparks+=sh;R.shardAcc=(R.shardAcc||0)+sh;}\n  hooks.kill(E,sp,sh);\n  if(R.mode==='boss'){R.mode='farm';S.run.fled=false;clearLocks();}\n  if(S.run.fled){R.E=enemyFor(n);R.E.hp=R.E.max;return;} // ferme sur l'étape précédente\n  S.run.stage=n+1;S.run.max=Math.max(S.run.max,S.run.stage);if(S.run.stage>S.maxStage)S.maxStage=S.run.stage;if(S.run.stage>S.bestStage){S.bestStage=S.run.stage;hooks.evolve();}\n  R.E=enemyFor(S.run.stage);\n  if(S.run.stage%10===0){R.mode='boss';R.bossT=CFG.enemy.bossTime;R.E.atkT=CFG.enemy.atkEvery;hooks.bossStart(R.E);}\n  if(S.up.au_prestige)maybeAutoPrestige();\n}\nfunction clearLocks(){for(let i=0;i<R.cells.length;i++)if(R.cells[i]&&R.cells[i].k==='lock'){R.cells[i]=null;hooks.unlock(i);}}\nfunction bossFlee(voluntary){clearLocks();R.mode='farm';S.run.fled=true;S.run.fledAt=R.t;R.retryT=0;R.E=enemyFor(S.run.stage-1);hooks.bossFled(voluntary);}\nfunction retreat(){if(!R||R.mode!=='boss')return false;bossFlee(true);return true;} // repli volontaire : on retourne farmer l'étape précédente\nfunction challengeBoss(){if(!R||R.mode!=='farm'||!S.run.fled)return false;S.run.fled=false;R.mode='boss';R.bossT=CFG.enemy.bossTime;R.E=enemyFor(S.run.stage);R.E.atkT=CFG.enemy.atkEvery;hooks.bossStart(R.E);return true;}\n/* ---------- Titan ---------- */\nconst TITAN_DAYS={get 0(){return dayName(0)},get 1(){return dayName(1)},get 2(){return dayName(2)},get 3(){return dayName(3)},get 4(){return dayName(4)},get 5(){return dayName(5)},get 6(){return dayName(6)}};\nconst dayName=i=>(I18N[LANG]._days||I18N.fr._days)[i];\nconst isTitanDay=(t=Date.now())=>CFG.titan.days.includes(dayOfWeek(t));\nfunction nextTitanDay(t=Date.now()){for(let k=1;k<=7;k++){const tk=t+k*86400e3;if(isTitanDay(tk))return TITAN_DAYS[dayOfWeek(tk)];}return '';}\nfunction titanState(){roll();if(!S.titan||S.titan.k!==dayKey())S.titan={k:dayKey(),used:0,ad:0,gem:0};return S.titan;}\nconst titanTickets=()=>{const t=titanState();return CFG.titan.free+(S.up.au_titan||0)+t.ad+t.gem-t.used;};\nconst titanReady=()=>isTitanDay()&&titanTickets()>0;\nfunction titanAdTicket(){const t=titanState();if(t.ad>=1)return false;t.ad++;return true;}\nfunction titanGemTicket(){const t=titanState();if(t.gem>=1||S.gems<CFG.titan.ticketGems)return false;S.gems-=CFG.titan.ticketGems;t.gem++;return true;}\nfunction startTitan(){if(!R||R.mode!=='farm'||!titanReady())return false;R.saved=R.E;R.E=titanEnemy();R.mode='titan';R.titanT=CFG.titan.time;R.titanDmg=0;titanState().used++;S.st.titans++;S.day.titans++;S.week.titans++;return true;}\nfunction endTitan(){const d=Math.floor(R.titanDmg);S.week.best+=d;if(d>S.st.titanBest)S.st.titanBest=d;R.E=R.saved||enemyFor(S.run.stage);R.mode='farm';hooks.titanEnd(d);}\n/* ---------- prestige ---------- */\nconst prestigeGain=()=>S.run.max>=CFG.prestige.minStage?Math.floor(CFG.prestige.shards(S.run.max)*lootMult()):0;\nfunction doPrestige(){\n  const g=prestigeGain();if(!g)return 0;\n  S.pp=(S.pp||0)+ppGain(S.run.max)+(S.prestiges?0:CFG.prestige.first);S.prestiges++;roll();S.day.prestiges++;S.week.prestiges++;\n  // Attaque, Plateau, Économie : remis à zéro, mais mémorisés (une recherche en cours compte comme acquise)\n  S.mem=S.mem||{};const reset=u=>!u.joker&&CFG.refr.reset.includes(u.g);\n  for(const b of S.build){const u=upById(b.id);if(u&&reset(u))S.mem[u.id]=Math.max(S.mem[u.id]||0,lvlOf(u)+1);}\n  S.build=S.build.filter(b=>{const u=upById(b.id);return !(u&&reset(u));});\n  for(const u of UPG)if(reset(u)){S.mem[u.id]=Math.max(S.mem[u.id]||0,S.up[u.id]||0);S.up[u.id]=0;}\n  S.run={sparks:g+50*Math.pow(2.2,S.up.st_bank)*(S.up.st_bank?1:0),stage:1,tb:{cad:0,birth:0,auto:0,power:0,spark:0},max:1,fled:false,fledAt:0,rate:0,srate:0,krate:0};\n  S.run.cells=null;if(R){const N=boardN();if(R.N!==N){R.N=N;R.cells=Array(N*N).fill(null);hooks.grow&&hooks.grow(N);}R.cells.fill(null);R.mode='farm';R.E=enemyFor(1);R.combo=0;R.burn=null;R.dmgWin=[];R.sparkWin=[];R.baseWin=[];R.killWin=[];for(let i=0;i<3;i++)spawnOne();}\n  hooks.prestige(g);return g;\n}\nfunction maybeAutoPrestige(){const g=prestigeGain(),thr=[1,0.5,0.25,0.1,0.05][Math.min(S.up.au_prestige-1,4)];if(g>0&&g>=Math.max(50,S.run.sparks*thr)){if(hooks.autoPrestige)hooks.autoPrestige();else doPrestige();}} // v11.6 : côté téléphone, passe par le serveur (sinon Réfraction perdue)\n/* ---------- hors-ligne ---------- */\nfunction offlineGains(now=Date.now()){\n  const el=(now-S.lastSeen)/1000;if(el<30)return null;\n  const capS=(2+S.up.off+(premOn()?CFG.pass.perks.offH:0))*3600,sec=Math.min(el,capS);\n  const sparks=Math.floor((S.run.srate||0)*sec*CFG.offline.factor*bonusMul('off'));\n  let stages=0;if(S.up.au_exped&&S.run.krate){const expS=Math.min(el,2*S.up.au_exped*3600);stages=Math.floor(S.run.krate*expS*0.5);\n    const maxAdv=Math.max(0,(Math.floor((S.run.stage-1)/10)+1)*10-1-S.run.stage); // jamais au-delà du prochain boss\n    stages=Math.min(stages,maxAdv);}\n  return {sec,sparks,stages,elapsed:el};\n}\nfunction applyOffline(o,mult=1){S.run.sparks+=o.sparks*mult;if(o.stages){S.run.stage+=o.stages;S.run.max=Math.max(S.run.max,S.run.stage);S.maxStage=Math.max(S.maxStage,S.run.stage);S.bestStage=Math.max(S.bestStage,S.run.stage);if(R){R.E=enemyFor(S.run.stage);}}}\n/* ---------- jokers ---------- */\nfunction placeJokerPiece(){if(R.cells.filter(c=>c&&c.k==='joker').length>=3)return -1;let e=emptyCells();let i;if(e.length)i=e[Math.floor(Math.random()*e.length)];else{i=R.cells.reduce((m,c,j)=>c&&c.l&&(m<0||c.l<R.cells[m].l)?j:m,-1);if(i<0)return -1;}R.cells[i]={k:'joker'};hooks.spawn(i);return i;}\nfunction useJoker(id){\n  if(!R||R.jk[id]==null||R.jk[id]<jokerNeed(id))return false;\n  const l=S.jk[id]||1;R.jk[id]=0;S.st.jokerUses++;roll();S.day.jokers++;\n  if(id==='chameleon'){placeJokerPiece();if(l>=4)placeJokerPiece();}\n  else if(id==='magnet'){let n=2+l;while(n-->0){if(!autoMerge())break;}}\n  else if(id==='surge'){R.surgeUntil=R.t+6+2*l;}\n  else if(id==='frost'){R.frostUntil=R.t+8+2*l;if(R.mode==='boss')R.bossT+=4+l;}\n  else if(id==='prism'){shapes().sort((a,b)=>a[0].l-b[0].l).slice(0,2+l).forEach(([c,i])=>{c.l++;hooks.spawn(i);});}\n  else if(id==='meteor'){const best=Math.max(spawnLevel(),...shapes().map(x=>x[0].l));applyDamage(null,dmgOf(best+2)*(1+0.5*(l-1))*powerMult(),false,null);}\n  else if(id==='breaker'){R.breakUntil=R.t+8+3*l;}\n  hooks.joker(id);return true;\n}\n\n/* ================= forme du joueur ================= */\nconst TIERS={length:10};for(let i=0;i<10;i++)Object.defineProperty(TIERS,i,{get(){return t('tier'+i)}});\nfunction tierOf(stage){const k=Math.floor((stage-1)/10);return k>=TIERS.length?{sides:0,name:t('circle')}:{sides:3+k,name:TIERS[k]};}\nconst layers=()=>Math.min(5,Math.floor((S.bestStage-1)/10));\n\n/* ================= quêtes ================= */\nconst DPOOL=[\n  {k:'q_kill',a:{n:20},v:()=>S.day.kills,n:20,r:{g:10}},\n  {k:'q_merge',a:{n:200},v:()=>S.day.merges,n:200,r:{s:80}},\n  {k:'q_ad',v:()=>S.day.ads,n:1,r:{b:1}},\n  {k:'q_boss1',v:()=>S.day.bosses,n:1,r:{g:10}},\n  {k:'q_tb',a:{n:15},v:()=>S.day.tb||0,n:15,r:{g:10}},\n  {k:'q_gift',a:{n:2},v:()=>S.day.gifts||0,n:2,r:{s:60}},\n  {k:'q_jok3',v:()=>S.day.jokers,n:3,r:{s:150}},\n  {k:'q_combo',a:{n:8},v:()=>S.day.combo,n:8,r:{b:1}},\n  {k:'q_pre1',v:()=>S.day.prestiges,n:1,r:{g:15}},\n  {k:'q_kill',a:{n:60},v:()=>S.day.kills,n:60,r:{s:300}},\n].map(q=>Object.defineProperty(q,'t',{get(){return t(q.k,q.a)},enumerable:true})); /* v11.8 : Object.assign figeait le texte dans la langue du démarrage */\nconst dayHash=k=>{let h=0;for(const ch of k)h=(h*31+ch.charCodeAt(0))>>>0;return h;};\nlet DAILY=[];\nfunction pickDaily(){const h=dayHash(S.day.k),base=DPOOL.slice(0,4),extra=DPOOL.slice(4);const a=base[h%4],b=base[(h>>>2)%4]===a?base[(h%4+1)%4]:base[(h>>>2)%4]; /* v12 : >>> (avec >>, les quêtes du jour cassaient dès le 1er janvier 2027) */\n  DAILY=[a,b,extra[h%extra.length],{get t(){return t('q_bonus')},v:()=>DAILY.slice(0,3).every(q=>q.v()>=q.n)?1:0,n:1,r:{g:15}}];}\n/* v12 : quêtes de la semaine tirées chaque lundi, une par famille (le jeu se renouvelle sans intervention) */\nconst WFAM=[\n  [{k:'q_kill',a:{n:300},v:()=>S.week.kills,n:300,r:{g:50}},{k:'q_kill',a:{n:600},v:()=>S.week.kills,n:600,r:{g:80}},{k:'q_bossw',a:{n:15},v:()=>S.week.bosses|0,n:15,r:{g:60}}],\n  [{k:'q_titan_n',a:{n:3},v:()=>S.week.titans,n:3,r:{b:3}},{k:'q_titan_n',a:{n:4},v:()=>S.week.titans,n:4,r:{b:4}}],\n  [{k:'q_top10',v:()=>myRank()<=10?1:0,n:1,r:{g:30}},{k:'q_merge',a:{n:2000},v:()=>S.week.merges|0,n:2000,r:{g:40}}],\n  [{k:'q_pre_n',a:{n:2},v:()=>S.week.prestiges,n:2,r:{s:1500}},{k:'q_pre_n',a:{n:3},v:()=>S.week.prestiges,n:3,r:{s:2000}}],\n].map(f=>f.map(q=>Object.defineProperty(q,'t',{get(){return t(q.k,q.a)},enumerable:true})));\nconst WEEKLY=[];\nfunction pickWeekly(){const h=dayHash('w'+S.week.k);WEEKLY.length=0;WFAM.forEach((f,i)=>WEEKLY.push(f[(h>>>(i*3))%f.length]));}\n/* v12 : événement automatique du week-end, un différent chaque semaine */\nconst EVENTS=['spark','joker','build','gift'];\nfunction weekendEvent(t=Date.now()){const dw=dparts(t)[3];if(dw!==6&&dw!==0)return null;const wk=Math.floor((seasonDay(t)-(dw===0?1:0))/7);return EVENTS[((wk%EVENTS.length)+EVENTS.length)%EVENTS.length];}\nfunction nextEvent(t=Date.now()){const dw=dparts(t)[3];const toSat=(6-dw+7)%7;return weekendEvent(t+toSat*864e5)||EVENTS[0];}\nconst evOn=(id,t)=>weekendEvent(t)===id; /* v11.8 : Object.assign figeait le texte dans la langue du démarrage */\nconst bossTotal=()=>S.st.bosses;\nconst jokersOwned=()=>Object.keys(S.jk).length;\nconst maxJokerLvl=()=>Math.max(0,...Object.values(S.jk));\nconst Q=(k,v,n,r,a)=>({k,a,v,n,r,get t(){return t(k,a)}});\nconst ONB=[\n  Q('o1',()=>S.st.manual,10,{g:10}),\n  Q('q_kill',()=>S.st.kills,3,{sp:100},{n:3}),\n  Q('o3',()=>Object.values(S.run.tb).reduce((a,b)=>a+b,0)+S.prestiges*5,1,{s:50}),\n  Q('o4',()=>S.bestStage,5,{g:10},{n:5}),\n  Q('o5',()=>S.st.started,1,{s:100}),\n  Q('o6',()=>S.bestStage,6,{sp:400}),\n  Q('o7',()=>S.st.gifts||0,1,{g:10}),\n  Q('o4',()=>S.bestStage,10,{g:20},{n:10}),\n  Q('o9',bossTotal,1,{s:300}),\n  Q('o10',()=>S.prestiges,1,{g:30,b:2}),\n  Q('o11',()=>S.st.bought,3,{s:200},{n:3}),\n  Q('o12',()=>Math.max(S.run.tb.auto,S.up.st_auto,S.up.au_merge),1,{g:20}),\n  Q('o13',()=>S.st.titans,1,{g:15}),\n  Q('o14',jokersOwned,1,{sp:2000}),\n  Q('o15',()=>S.st.maxCombo,10,{g:15}),\n  Q('o4',()=>S.bestStage,20,{s:800},{n:20}),\n  Q('o17',()=>S.prestiges,3,{g:25},{n:3}),\n  Q('o18',()=>S.up.st_power,5,{s:1500}),\n  Q('q_kill',()=>S.st.kills,100,{b:2},{n:100}),\n  Q('o20',()=>S.st.days,2,{g:20},{n:2}),\n  Q('o4',()=>S.bestStage,30,{s:3000},{n:30}),\n  Q('o11',()=>S.st.bought,12,{g:30},{n:12}),\n  Q('o23',()=>S.up.au_buy,1,{g:40}),\n  Q('o24',()=>S.st.jokerUses,15,{s:4000}),\n  Q('o17',()=>S.prestiges,6,{g:30},{n:6}),\n  Q('o26',bossTotal,5,{s:6000},{n:5}),\n  Q('o20',()=>S.st.days,3,{b:4},{n:3}),\n  Q('o4',()=>S.bestStage,40,{g:40},{n:40}),\n  Q('o29',jokersOwned,2,{s:10000},{n:2}),\n  Q('o30',()=>S.st.titanBest,1e6,{g:30},{n:fmt(1e6)}),\n  Q('o31',()=>S.up.au_joker,1,{g:50}),\n  Q('o11',()=>S.st.bought,25,{s:20000},{n:25}),\n  Q('o17',()=>S.prestiges,10,{g:40},{n:10}),\n  Q('q_kill',()=>S.st.kills,500,{b:6},{n:500}),\n  Q('o4',()=>S.bestStage,50,{s:40000},{n:50}),\n  Q('o20',()=>S.st.days,5,{g:40},{n:5}),\n  Q('o37',()=>S.up.au_exped,1,{g:60}),\n  Q('o38',maxJokerLvl,3,{s:60000}),\n  Q('o29',jokersOwned,4,{g:60},{n:4}),\n  Q('o26',bossTotal,10,{s:100000},{n:10}),\n  Q('o4',()=>S.bestStage,60,{g:60},{n:60}),\n  Q('o42',()=>S.up.au_prestige,1,{g:80}),\n  Q('o11',()=>S.st.bought,40,{s:200000},{n:40}),\n  Q('o30',()=>S.st.titanBest,1e8,{b:8},{n:fmt(1e8)}),\n  Q('o17',()=>S.prestiges,20,{g:60},{n:20}),\n  Q('o20',()=>S.st.days,7,{g:80,b:8},{n:7}),\n  Q('o4',()=>S.bestStage,75,{s:500000},{n:75}),\n  Q('o26',bossTotal,20,{g:80},{n:20}),\n  Q('o11',()=>S.st.bought,60,{s:1000000},{n:60}),\n  Q('o4',()=>S.bestStage,100,{g:200,b:12},{n:100}),\n];\nfunction questView(){\n  roll();\n  const mk=(arr,claimed,kind)=>arr.map((q,i)=>({i,kind,t:q.t,p:Math.min(q.v(),q.n),n:q.n,r:q.r,done:claimed.includes(i)}));\n  const onb=mk(ONB,S.onb,'o').filter(q=>!q.done).slice(0,3);\n  return {onb,onbLeft:ONB.length-S.onb.length,d:mk(DAILY,S.day.claimed,'d'),w:mk(WEEKLY,S.week.claimed,'w')};\n}\nfunction claim(kind,i){\n  roll();const arr={o:ONB,d:DAILY,w:WEEKLY}[kind],cl={o:S.onb,d:S.day.claimed,w:S.week.claimed}[kind];\n  const q=arr[i];if(!q||cl.includes(i)||q.v()<q.n)return false;\n  if(kind==='o'){const vis=ONB.map((_,j)=>j).filter(j=>!S.onb.includes(j)).slice(0,3);if(!vis.includes(i))return false;}\n  cl.push(i);give(q.r);chestFill(q.r.g|0);passXP(CFG.pass.q[kind]||0);return true;\n}\nconst claimable=()=>{const v=questView();return v.onb.concat(v.d,v.w).some(q=>!q.done&&q.p>=q.n);};\n\n/* ================= guilde : quêtes du jour (points) et paliers ================= */\nconst GPOOL=[\n  {k:'q_kill',a:{n:30},v:()=>S.day.kills,n:30,p:10},\n  {k:'q_merge',a:{n:150},v:()=>S.day.merges,n:150,p:10},\n  {k:'q_tb',a:{n:10},v:()=>S.day.tb||0,n:10,p:10},\n  {k:'gq_research',a:{n:2},v:()=>S.day.started||0,n:2,p:20},\n  {k:'q_boss1',v:()=>S.day.bosses,n:1,p:20},\n  {k:'q_gift',a:{n:2},v:()=>S.day.gifts||0,n:2,p:20},\n  {k:'q_jok3',v:()=>S.day.jokers,n:3,p:20},\n  {k:'q_kill',a:{n:100},v:()=>S.day.kills,n:100,p:30},\n  {k:'q_pre1',v:()=>S.day.prestiges,n:1,p:30},\n  {k:'gq_titan',v:()=>S.day.titans,n:1,p:30},\n].map(q=>Object.defineProperty(q,'t',{get(){return t(q.k,q.a)},enumerable:true})); /* v11.8 : Object.assign figeait le texte dans la langue du démarrage */\n/* 3 quêtes par jour, une par niveau de points (10/20/30), tirées de la date : identiques sur le téléphone et le serveur */\nfunction guildQuests(){roll();const h=dayHash(S.day.k+'g'),out=[];CFG.guild.pts.forEach((pts,lvl)=>{let pool=GPOOL.map((q,i)=>({q,i})).filter(x=>x.q.p===pts&&(x.q.k!=='gq_titan'||isTitanDay()));const x=pool[(h>>>(lvl*3))%pool.length];out.push({i:x.i,t:x.q.t,p:Math.min(x.q.v(),x.q.n),n:x.q.n,pts,done:(S.day.gq||[]).includes(x.i)});});return out;}\n/* valide une quête de guilde : renvoie ses points (0 si non remplie, déjà validée ou absente du tirage du jour) */\nfunction guildQuestDone(i){const q=guildQuests().find(x=>x.i===i);if(!q||q.done||q.p<q.n)return 0;S.day.gq.push(i);return q.pts;}\nconst guildClaimable=()=>guildQuests().some(q=>!q.done&&q.p>=q.n);\n/* récompense d'un palier (1..5) pour un membre : gemmes + étincelles en minutes de production (+ boost au dernier) */\nfunction guildReward(tier){const r=CFG.guild.rewards[tier-1];if(!r)return null;return {g:r.g,min:r.min,b:r.b||0,sparks:Math.max(CFG.ads.floor.shop,Math.floor(rateMin()*r.min))};}\n\n/* ================= ligue simulée ================= */\nfunction ensureLeague(){\n  roll();if(S.league&&S.league.k===S.week.k)return;\n  const base=Math.max(S.st.titanBest*0.8,2000);\n  S.league={k:S.week.k,start:Date.now(),base,div:'Bronze',bots:Array.from({length:29},()=>({name:randomName(),k:Math.exp(rnd(-1.3,1.1)),ph:rnd(0,6.28),sides:3+Math.floor(rnd(0,8)),hue:Math.floor(rnd(0,360))}))};\n}\nfunction standings(){\n  ensureLeague();const el=(Date.now()-S.league.start)/1000;const g=Math.min(1,0.25+el/(3*86400));\n  const rows=S.league.bots.map(b=>({name:b.name,score:Math.floor(S.league.base*b.k*g*(1+0.08*Math.sin(el/3600+b.ph))*(1+el/86400)),sides:b.sides,hue:b.hue}));\n  rows.push({name:S.name,score:S.week.best,sides:tierOf(S.bestStage).sides,me:true});\n  rows.sort((a,b)=>b.score-a.score||(a.me?1:-1));return rows;\n}\nconst myRank=()=>standings().findIndex(r=>r.me)+1;\n\n/* ================= pseudo, boutique ================= */\nconst RENAME=50;\nfunction rename(raw){const c=checkName(raw);if(!c.ok)return c;if(S.nameChanges>0){if(S.gems<RENAME)return {ok:false,msg:t('name_cost',{n:RENAME})};S.gems-=RENAME;}S.nameChanges++;S.name=c.name;S.flagged=0;return {ok:true};}\nfunction reportMe(){S.flagged++;if(S.flagged>=3){S.name=randomName();S.flagged=0;return 'reset';}return 'noted';}\nconst OFFERS=[\n  {id:'starter',price:1.99,once:()=>S.starter,give(){give({g:300,b:6});S.starter=true;},get t(){return t('of_starter')},get d(){return t('of_starter_d')}},\n  {id:'loot',price:7.99,once:()=>S.lootX2,give(){S.lootX2=true;},get t(){return t('of_loot')},get d(){return t('of_loot_d')}},\n  {id:'chest',price:CFG.chest.price,avail:()=>chestG()>=CFG.chest.open,give(){const g=chestG();S.gems+=g;S.chest=0;S.st.chests=(S.st.chests|0)+1;},get t(){return t('of_chest')},get d(){return t('of_chest_d',{n:grp(chestG()),m:grp(CFG.chest.cap),o:grp(CFG.chest.open)})}},\n  {id:'pass',price:CFG.pass.price,once:()=>passState().prem,give(){passState().prem=true;},get t(){return t('of_pass')},get d(){return t('of_pass_d',{n:grp(PASS.reduce((a,x)=>a+(x.p.g|0),0)),h:CFG.pass.perks.offH,d:seasonLeft()})}},\n  {id:'noads',price:2.99,once:()=>S.noAds,give(){S.noAds=true;},get t(){return t('of_noads')},get d(){return t('of_noads_d')}},\n].concat([[100,0.99],[600,4.99],[1300,9.99],[2800,19.99],[7500,49.99],[16000,99.99]].map(([n,price],i)=>({id:'g'+n,price,n,give(){S.gems+=S.firstX2?n:2*n;S.firstX2=true;},get t(){return t('of_gems',{n:grp(n)})},get d(){return i?t('of_more',{n:packBonus(this)}):t('of_small')}})));\n/* v9.7 : 100 gemmes = 0,99 € (taux de référence du plus petit pack, principe CPC 1) ; bonus affiché = bonus réel arrondi vers le bas */\nconst GEM_REF={n:100,price:0.99};\nconst packBonus=o=>Math.floor(100*((o.n/o.price)/(GEM_REF.n/GEM_REF.price))-100+1e-9);\nconst adLeft=k=>Math.max(0,CFG.ads.cap[k]-((S.day.adk||{})[k]|0));\nfunction adUse(k){S.day.adk=Object.assign({},S.day.adk);S.day.adk[k]=(S.day.adk[k]|0)+1;}\n/* prix affichés : devise locale de démonstration (dans l'app réelle, le store fournit le prix) */\nconst CUR={fr:'EUR',de:'EUR',es:'EUR',it:'EUR',pt:'EUR',en:'USD',ja:'JPY',ko:'KRW',zh:'CNY',ru:'RUB',tr:'TRY',pl:'PLN',id:'IDR',hi:'INR',ar:'USD',nl:'EUR',sv:'SEK'};\nconst RATE={EUR:1,USD:1,JPY:150,KRW:1400,CNY:7.5,RUB:100,TRY:35,PLN:4.3,IDR:16000,INR:85,SEK:11.5};\nfunction priceOf(o){const cur=CUR[LANG]||'USD',v=o.price*(RATE[cur]||1);try{return new Intl.NumberFormat(LANG,{style:'currency',currency:cur,maximumFractionDigits:cur==='JPY'||cur==='KRW'||cur==='IDR'?0:2}).format(cur==='JPY'||cur==='KRW'||cur==='IDR'?Math.round(v/10)*10-1:v);}catch(e){return o.price+' €';}}\nconst eurOf=g=>'≈ '+priceOf({price:g*GEM_REF.price/GEM_REF.n}); // équivalent en monnaie réelle d'un prix en gemmes\nfunction purchase(id){const o=OFFERS.find(x=>x.id===id);if(!o||(o.once&&o.once())||(o.avail&&!o.avail())||!canPay())return false;o.give();addSpend(o.price);return true;}\n/* v10.5 : plus d'écran d'âge (jeu 16+) : les achats passent par le compte Google ou Apple et ses contrôles parentaux ; suivi des dépenses du mois pour l'alerte */\nconst canPay=()=>true;\nconst monthKey=(t=Date.now())=>{const [y,m]=dparts(t);return y+'-'+(m+1);};\nfunction spendNow(){const m=monthKey();if(!S.spend||S.spend.m!==m)S.spend={m,eur:0};return S.spend;}\nfunction addSpend(p){const s=spendNow();s.eur=Math.round((s.eur+p)*100)/100;}\n/* v10 : pass de saison */\n/* v11 : gratuit = 2 gemmes un palier sur deux, 10 min de production sinon ; premium = 8 gemmes, 50 tous les 10 paliers, boost 4 h aux paliers 25/50/75/100, couleur Saison au 100 (≈ 1 220 gemmes) */\n/* v12 : premium = 8 gemmes, coffre (2 h de production + boost 2 h) tous les 5 paliers, 80 gemmes tous les 10, couleur de la saison au 50 et sa version Éclat au 100 */\nconst PASS=Array.from({length:CFG.pass.tiers},(_,i)=>{const n=i+1;return {f:n%2?{m:10}:{g:2},p:Object.assign(n%10===0?{g:80}:n%5===0?{m:120,b:2,chest:1}:{g:8},n===50?{skin:'S'}:{},n===CFG.pass.tiers?{skin:'SX'}:{})};});\nconst SEASON0=Date.UTC(2026,0,5); // un lundi : les saisons durent 4 semaines\nfunction seasonDay(t=Date.now()){const [y,m,d]=dparts(t);return Math.floor((Date.UTC(y,m,d)-SEASON0)/864e5);}\nconst seasonKey=(t=Date.now())=>Math.floor(seasonDay(t)/28);\nconst seasonLeft=(t=Date.now())=>28-((seasonDay(t)%28)+28)%28; // jours restants, aujourd'hui compris\nfunction passState(){const k=seasonKey();if(!S.pass||S.pass.k!==k||S.pass.v!==CFG.pass.v)S.pass={k,v:CFG.pass.v,xp:S.pass&&S.pass.k===k?Math.min(S.pass.xp|0,CFG.pass.tiers*CFG.pass.xp):CFG.pass.xp, /* v12.3 : palier 1 offert à chaque nouvelle saison (progression amorcée) */prem:!!(S.pass&&S.pass.k===k&&S.pass.prem),cf:[],cp:[]};return S.pass;}\n/* v12 : avantages du pass payant, actifs pendant sa saison */\nfunction premOn(){const p=S.pass;return !!(p&&p.prem&&p.k===seasonKey());}\nconst slotsN=()=>S.slots+(premOn()?CFG.pass.perks.slot:0);\n/* v12 : saisons générées automatiquement : nom, teinte et gemme exclusive à partir du numéro de saison */\nconst seasonHue=k=>Math.round(((k*137.508)%360+360)%360);\nconst seasonName=k=>t('sn_'+(((k%12)+12)%12));\nconst isSeasonSkin=id=>/^s\\d+x?$/.test(id);\nfunction skinInfo(id){if(isSeasonSkin(id)){const k=parseInt(id.slice(1)),x=id.endsWith('x');return {id,season:k,x,hue:seasonHue(k),bn:x?{dmg:0.1,sp:0.1}:{sp:0.08},get label(){return x?t('sn_x',{n:seasonName(k)}):seasonName(k);}};}const s=SKINS.find(z=>z.id===id);return s?Object.assign({hue:s.h,bn:s.bn||{}},s,{label:s.label}):null;}\n/* v12.1 : médailles (succès en 4 rangs : bronze, argent, or, diamant), bonus permanent selon la difficulté */\nconst MEDAL_RANK=[0.01,0.02,0.03,0.05],MEDAL_GEMS=[5,15,40,100]; // v12.5 : paliers recalés sur la simulation (joueur moyen : bronze en quelques jours, argent ~2 semaines, or ~2 mois, diamant ≥ 6 mois) ; récompense plus forte pour les derniers rangs\nconst MEDALS=[\n  {id:'explore',ic:'flag',k:'dmg',q:1.5,th:[30,60,120,200],v:()=>S.bestStage},\n  {id:'hunt',ic:'swords',k:'sp',q:1,th:[100,1000,5000,25000],v:()=>S.st.kills},\n  {id:'boss',ic:'trophy',k:'dmg',q:1.2,th:[10,50,300,1500],v:()=>S.st.bosses},\n  {id:'alch',ic:'prism',k:'cad',q:1,th:[5000,40000,300000,2e6],v:()=>S.st.merges},\n  {id:'artisan',ic:'hammer',k:'sp',q:1.2,th:[300,2000,6000,20000],v:()=>S.st.manual},\n  {id:'refr',ic:'diamond',k:'sp',q:1.5,th:[1,10,40,150],v:()=>S.prestiges},\n  {id:'titan',ic:'flame',k:'dmg',q:1.2,th:[3,15,80,300],v:()=>S.st.titans|0},\n  {id:'research',ic:'anvil',k:'res',q:1,th:[25,250,3000,20000],v:()=>S.st.bought},\n  {id:'collect',ic:'gem',k:'off',q:1,th:[3,6,10,16],v:()=>S.skins.length},\n  {id:'loyal',ic:'heart',k:'sp',q:1.5,th:[7,30,120,365],v:()=>S.st.days},\n  {id:'joker',ic:'star',k:'jok',q:1,th:[100,2000,30000,300000],v:()=>S.st.jokerUses},\n  {id:'season',ic:'crown',k:'dmg',q:1.5,th:[1,4,10,20],v:()=>S.skins.filter(isSeasonSkin).length},\n].map(m=>Object.defineProperty(m,'t',{get(){return t('md_'+m.id)},enumerable:true}));\nconst medalLvl=id=>((S.medals||{})[id]|0);\nconst medalBonusOf=(m,l)=>MEDAL_RANK.slice(0,l).reduce((a,x)=>a+x,0)*m.q;\nconst medalReady=m=>medalLvl(m.id)<4&&m.v()>=m.th[medalLvl(m.id)];\nfunction claimMedal(id){const m=MEDALS.find(x=>x.id===id);if(!m||!medalReady(m))return false;const l=medalLvl(id);S.medals=S.medals||{};S.medals[id]=l+1;S.gems+=MEDAL_GEMS[l];return true;}\nconst medalsReady=()=>MEDALS.some(medalReady);\n/* bonus total d'un type : couleur portée × médailles × collection (+1 % d'étincelles par couleur possédée au-delà de la première) */\nfunction bonusMul(k){const sk=skinInfo(S.skin),w=(sk&&sk.bn&&sk.bn[k])||0;const md=MEDALS.reduce((a,m)=>a+(m.k===k?medalBonusOf(m,medalLvl(m.id)):0),0);const col=k==='sp'?0.01*Math.max(0,(S.skins||[]).length-1):0;return (1+w)*(1+md)*(1+col);}\n/* v12 : offre de la semaine (gemmes), une par semaine, qui change seule */\nconst weekOffer=()=>{const L=CFG.weekOffer,h=dayHash('o'+weekKey());return L[h%L.length];};\nfunction buyWeekOffer(){roll();const o=weekOffer();if(S.week.wo||S.gems<o.g)return false;S.gems-=o.g;S.week.wo=1;if(o.m)S.run.sparks+=Math.max(Math.round(CFG.ads.floor.shop*o.m/30),Math.floor(rateMin()*o.m));if(o.b)give({b:o.b});return true;}\nfunction passXP(n){if(!n)return;const p=passState();if(p.prem)n*=CFG.pass.perks.xp;p.xp=Math.min(CFG.pass.tiers*CFG.pass.xp,p.xp+n);}\nconst passTier=()=>Math.floor(passState().xp/CFG.pass.xp);\nfunction passClaim(n,track){const p=passState();n=n|0;const prem=track==='p';if(n<1||n>CFG.pass.tiers||passTier()<n||(prem&&!p.prem))return false;const cl=prem?p.cp:p.cf;if(cl.includes(n))return false;cl.push(n);const r=PASS[n-1][prem?'p':'f'];\n  if(r.skin){const id=r.skin==='S'?'s'+p.k:r.skin==='SX'?'s'+p.k+'x':r.skin;if(S.skins.includes(id))S.gems+=CFG.pass.dupe;else S.skins.push(id);}\n  if(r.m)S.run.sparks+=Math.max(Math.round(CFG.ads.floor.shop*r.m/30),Math.floor(rateMin()*r.m));\n  give({g:r.g,b:r.b});if(!prem)chestFill(r.g|0);return true;}\n/* v11 : acheter des paliers avec des gemmes (ouvert à tous ; sans pass payant, seuls les paliers gratuits deviennent récupérables) */\nconst passTierCost=k=>k>=10?Math.round(CFG.pass.tier10*k/10):k*CFG.pass.tierGems;\nfunction passBuy(k){const p=passState(),n=passTier();k=Math.min(k|0,CFG.pass.tiers-n);if(k<1)return false;const g=passTierCost(k);if(S.gems<g)return false;S.gems-=g;p.xp=(n+k)*CFG.pass.xp;return true;}\nfunction passClaimAll(){const p=passState(),n=passTier();let c=0;for(let i=1;i<=n;i++){if(!p.cf.includes(i)&&passClaim(i,'f'))c++;if(p.prem&&!p.cp.includes(i)&&passClaim(i,'p'))c++;}return c;}\nconst passClaimable=()=>{const p=passState(),n=passTier();for(let i=1;i<=n;i++){if(!p.cf.includes(i)||(p.prem&&!p.cp.includes(i)))return true;}return false;};\n/* v10 : cadeau gratuit quotidien de la boutique */\nconst shopGiftG=()=>CFG.shopGift.g*(evOn('gift')?3:1); // v12 : week-end cadeau du jour ×3\nfunction shopGift(){roll();if(S.day.sgift)return false;S.day.sgift=1;const g=shopGiftG();S.gems+=g;chestFill(g);return true;}\nfunction buyGemItem(id){\n  if(id==='boost'){if(S.gems<CFG.boost.gemsPrice)return false;S.gems-=CFG.boost.gemsPrice;give({b:CFG.boost.gemsH});return true;}\n  if(id==='titan')return titanGemTicket();\n  return false;\n}\nfunction buySkin(id){if(isSeasonSkin(id)){if(!S.skins.includes(id))return false;S.skin=id;return true;}const k=SKINS.find(s=>s.id===id);if(!k)return false;if(S.skins.includes(id)){S.skin=id;return true;}if(k.pass||S.gems<k.price)return false;S.gems-=k.price;S.skins.push(id);S.skin=id;return true;}\n\n";
